     1→import { headers } from "next/headers";
     2→import { unauthorized } from "next/navigation";
     3→import { auth } from "../auth";
     4→
     5→export const getSession = async () => {
     6→  const session = await auth.api.getSession({
     7→    headers: await headers(),
     8→  });
     9→
    10→  return session;
    11→};
    12→
    13→export const getUser = async () => {
    14→  const session = await getSession();
    15→
    16→  if (!session?.user) {
    17→    return null;
    18→  }
    19→
    20→  const user = session.user;
    21→  return user;
    22→};
    23→
    24→export const getRequiredUser = async () => {
    25→  const user = await getUser();
    26→
    27→  if (!user) {
    28→    unauthorized();
    29→  }
    30→
    31→  return user;
    32→};
    33→
    34→export const getRequiredAdmin = async () => {
    35→  const user = await getRequiredUser();
    36→
    37→  if (user.role !== "admin") {
    38→    unauthorized();
    39→  }
    40→
    41→  return user;
    42→};
