     1→import type { User } from "better-auth";
     2→import { env } from "../env";
     3→import { resend } from "../mail/resend";
     4→import { prisma } from "../prisma";
     5→
     6→export const setupResendCustomer = async (user: User) => {
     7→  if (!user.email) {
     8→    return;
     9→  }
    10→
    11→  if (!env.RESEND_AUDIENCE_ID) {
    12→    return;
    13→  }
    14→
    15→  const contact = await resend.contacts.create({
    16→    audienceId: env.RESEND_AUDIENCE_ID,
    17→    email: user.email,
    18→    firstName: user.name || "",
    19→    unsubscribed: false,
    20→  });
    21→
    22→  if (!contact.data) return;
    23→
    24→  await prisma.user.update({
    25→    where: {
    26→      id: user.id,
    27→    },
    28→    data: {
    29→      resendContactId: contact.data.id,
    30→    },
    31→  });
    32→
    33→  return contact.data.id;
    34→};
