     6→  DPEServiceError,
     7→  DPENotFoundError,
     8→  DPEAPIError,
     9→} from "./types";
    10→import { normalizeDPERawData, validateDPEData } from "./utils";
    11→
    12→type DPEClientConfig = {
    13→  baseUrl?: string;
    14→  apiKey?: string;
    15→  timeout?: number;
    16→  maxRetries?: number;
    17→  rateLimitDelay?: number;
    18→}
    19→
    20→type DPERawRecord = {
    21→  fields?: Record<string, unknown>;
    22→  recordid?: string;
    23→};
    24→
    25→type DPERawResponse = {
    26→  records?: DPERawRecord[];
    27→  nhits?: number;
    28→  total_count?: number;
    29→  record?: {
    30→    fields?: Record<string, unknown>;
    31→  };
    32→}
    33→
    34→/**
    35→ * Client API pour les données DPE
    36→ * Supporte plusieurs sources : ADEME, data.gouv.fr, et APIs alternatives
    37→ */
    38→export class DPEClient {
    39→  private readonly baseUrl: string;
    40→  private readonly apiKey?: string;
    41→  private readonly timeout: number;
    42→  private readonly maxRetries: number;
    43→  private readonly rateLimitDelay: number;
    44→  private lastRequestTime = 0;
    45→
    46→  constructor(config: DPEClientConfig = {}) {
    47→    this.baseUrl = config.baseUrl ?? "https://data.ademe.fr/api";
    48→    this.apiKey = config.apiKey;
    49→    this.timeout = config.timeout ?? 30000;
    50→    this.maxRetries = config.maxRetries ?? 3;
    51→    this.rateLimitDelay = config.rateLimitDelay ?? 1000;
    52→  }
    53→
    54→  /**
    55→   * Recherche des diagnostics DPE par critères
    56→   */
    57→  async searchDPE(request: DPESearchRequest): Promise<DPESearchResponse> {
    58→    try {
    59→      await this.enforceRateLimit();
    60→      
    61→      const queryParams = this.buildSearchParams(request);
    62→      const response = await this.makeRequest("/datasets/dpe-france/records", queryParams);
    63→      
    64→      return this.parseSearchResponse(response);
    65→    } catch (error) {
    66→      if (error instanceof DPEServiceError) {
    67→        throw error;
    68→      }
    69→      throw new DPEAPIError(
    70→        `Erreur lors de la recherche DPE: ${error instanceof Error ? error.message : 'Erreur inconnue'}`,
    71→        undefined,
    72→        error
    73→      );
    74→    }
    75→  }
    76→
    77→  /**
    78→   * Recherche des DPE par adresse
    79→   */
    80→  async searchByAddress(address: string, limit = 10): Promise<DPE[]> {
    81→    return this.searchDPE({
    82→      address,
    83→      limit,
    84→    }).then(response => response.results);
    85→  }
    86→
    87→  /**
    88→   * Recherche des DPE par code postal
    89→   */
    90→  async searchByPostalCode(postalCode: string, limit = 50): Promise<DPE[]> {
    91→    return this.searchDPE({
    92→      postalCode,
    93→      limit,
    94→    }).then(response => response.results);
    95→  }
    96→
    97→  /**
    98→   * Recherche des DPE par coordonnées géographiques
    99→   */
   100→  async searchByCoordinates(
   101→    coordinates: [number, number],
   102→    radius = 0.1,
   103→    limit = 10
   104→  ): Promise<DPE[]> {
   105→    return this.searchDPE({
   106→      coordinates,
   107→      radius,
   108→      limit,
   109→    }).then(response => response.results);
   110→  }
   111→
   112→  /**
   113→   * Recherche des DPE par ville
   114→   */
   115→  async searchByCity(city: string, limit = 50): Promise<DPE[]> {
   116→    return this.searchDPE({
   117→      city,
   118→      limit,
   119→    }).then(response => response.results);
   120→  }
   121→
   122→  /**
   123→   * Récupère un DPE spécifique par son ID
   124→   */
   125→  async getDPEById(id: string): Promise<DPE> {
   126→    try {
   127→      await this.enforceRateLimit();
   128→      
   129→      const response = await this.makeRequest(`/datasets/dpe-france/records/${id}`);
   130→      
   131→      if (!response.record) {
   132→        throw new DPENotFoundError(`DPE avec l'ID ${id} non trouvé`);
   133→      }
   134→      
   135→      return this.parseSingleResponse(response.record);
   136→    } catch (error) {
   137→      if (error instanceof DPEServiceError) {
   138→        throw error;
   139→      }
   140→      throw new DPEAPIError(
   141→        `Erreur lors de la récupération du DPE ${id}: ${error instanceof Error ? error.message : 'Erreur inconnue'}`,
   142→        undefined,
   143→        error
   144→      );
   145→    }
   146→  }
   147→
   148→  /**
   149→   * Génère un mock DPE pour le développement
   150→   */
   151→  async generateMockDPE(address: string, postalCode: string, city: string): Promise<DPE> {
   152→    // Simuler un délai réseau
   153→    await new Promise(resolve => setTimeout(resolve, 100));
   154→    
   155→    const mockClasses = ["A", "B", "C", "D", "E", "F", "G"];
   156→    const energyClass = mockClasses[Math.floor(Math.random() * 4)]; // A-D pour plus de réalisme
   157→    const gesClass = mockClasses[Math.floor(Math.random() * 4)];
   158→    
   159→    const consumptionValues = {
   160→      A: { min: 20, max: 50 },
   161→      B: { min: 51, max: 90 },
   162→      C: { min: 91, max: 150 },
   163→      D: { min: 151, max: 230 },
   164→      E: { min: 231, max: 330 },
   165→      F: { min: 331, max: 450 },
   166→      G: { min: 451, max: 600 },
   167→    };
   168→    
   169→    const gesValues = {
   170→      A: { min: 0, max: 5 },
   171→      B: { min: 6, max: 10 },
   172→      C: { min: 11, max: 20 },
   173→      D: { min: 21, max: 35 },
   174→      E: { min: 36, max: 55 },
   175→      F: { min: 56, max: 80 },
   176→      G: { min: 81, max: 120 },
   177→    };
   178→    
   179→    const consumptionRange = consumptionValues[energyClass as keyof typeof consumptionValues];
   180→    const gesRange = gesValues[gesClass as keyof typeof gesValues];
   181→    
   182→    const consumption = Math.floor(
   183→      Math.random() * (consumptionRange.max - consumptionRange.min + 1) + consumptionRange.min
   184→    );
   185→    
   186→    const ges = Math.floor(
   187→      Math.random() * (gesRange.max - gesRange.min + 1) + gesRange.min
   188→    );
   189→    
   190→    const surface = Math.floor(Math.random() * 100) + 30; // 30-130 m²
   191→    const yearBuilt = Math.floor(Math.random() * 60) + 1964; // 1964-2024
   192→    
   193→    const mockData = {
   194→      id: `mock_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
   195→      address,
   196→      postalCode,
   197→      city,
   198→      coordinates: [
   199→        2.3522 + (Math.random() - 0.5) * 0.1, // Paris area + random offset
   200→        48.8566 + (Math.random() - 0.5) * 0.1,
   201→      ] as [number, number],
   202→      
   203→      propertyType: "apartment" as const,
   204→      surface,
   205→      yearBuilt,
   206→      livingArea: surface,
   207→      
   208→      energyConsumption: {
   209→        value: consumption,
   210→        unit: "kWh_ep/m².an",
   211→        maxAuthorized: 450,
   212→        class: energyClass,
   213→      },
   214→      
   215→      gesEmission: {
   216→        value: ges,
   217→        unit: "kgCO2/m².an",
   218→        maxAuthorized: 80,
   219→        class: gesClass,
   220→      },
   221→      
   222→      mainEnergyType: "electricity" as const,
   223→      
   224→      insulation: {
   225→        hasDoubleGlazing: Math.random() > 0.3,
   226→        wallInsulation: Math.random() > 0.5 ? "good" : "medium",
   227→        roofInsulation: Math.random() > 0.6 ? "good" : "medium",
   228→        floorInsulation: Math.random() > 0.4 ? "good" : "medium",
   229→      },
   230→      
   231→      equipment: {
   232→        hasVentilation: Math.random() > 0.2,
   233→        hasHeating: true,
   234→        hasHotWater: true,
   235→        hasCooling: Math.random() > 0.8,
   236→        heatingType: Math.random() > 0.5 ? "individual" : "collective",
   237→        hotWaterType: Math.random() > 0.5 ? "individual" : "collective",
   238→      },
   239→      
   240→      isRegulationCompliant: energyClass !== "F" && energyClass !== "G",
   241→      rentalRestrictionWarning: energyClass === "F" || energyClass === "G",
   242→      renovationRecommendation: energyClass === "F" || energyClass === "G" 
   243→        ? "Rénovation énergétique requise" 
   244→        : undefined,
   245→      
   246→      dpeDate: new Date(Date.now() - Math.random() * 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
   247→      dpeValidity: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
   248→      diagnostician: "Expert DPE",
   249→      dpeNumber: `DPE-${Math.random().toString(36).substr(2, 8).toUpperCase()}`,
   250→      dataSource: "mock",
   251→      lastUpdated: new Date().toISOString(),
   252→    };
   253→    
   254→    return validateDPEData(mockData);
   255→  }
   256→
   257→  /**
   258→   * Vérifie la santé de l'API
   259→   */
   260→  public async healthCheck(): Promise<boolean> {
   261→    try {
   262→      await this.makeRequest("/datasets/dpe-france/records", "rows=1");
   263→      return true;
   264→    } catch (error) {
   265→      console.debug("Health check DPE API failed:", error);
   266→      return false;
   267→    }
   268→  }
   269→
   270→  /**
   271→   * Obtient les statistiques de l'API
   272→   */
   273→  public async getStats(): Promise<{ totalRecords: number; lastUpdate: string }> {
   274→    try {
   275→      const response = await this.makeRequest("/datasets/dpe-france");
   276→      return {
   277→        totalRecords: response.nhits ?? 0,
   278→        lastUpdate: (response as { metas?: { last_update?: string } }).metas?.last_update ?? new Date().toISOString(),
   279→      };
   280→    } catch (error) {
   281→      throw new DPEAPIError("Impossible de récupérer les statistiques de l'API DPE", undefined, error);
   282→    }
   283→  }
   284→
   285→  /**
   286→   * Construit les paramètres de recherche
   287→   */
   288→  private buildSearchParams(request: DPESearchRequest): string {
   289→    const params = new URLSearchParams();
   290→    
   291→    if (request.address) {
   292→      params.append("q", request.address);
   293→    }
   294→    
   295→    if (request.postalCode) {
   296→      params.append("refine.code_postal", request.postalCode);
   297→    }
   298→    
   299→    if (request.city) {
   300→      params.append("refine.ville", request.city);
   301→    }
   302→    
   303→    if (request.coordinates) {
   304→      const [lng, lat] = request.coordinates;
   305→      params.append("geofilter.distance", `${lat},${lng},${request.radius}`);
   306→    }
   307→    
   308→    if (request.propertyType) {
   309→      params.append("refine.type_batiment", request.propertyType);
   310→    }
   311→    
   312→    if (request.minYearBuilt) {
   313→      params.append("refine.annee_construction_min", request.minYearBuilt.toString());
   314→    }
   315→    
   316→    if (request.maxYearBuilt) {
   317→      params.append("refine.annee_construction_max", request.maxYearBuilt.toString());
   318→    }
   319→    
   320→    if (request.minSurface) {
   321→      params.append("refine.surface_habitable_min", request.minSurface.toString());
   322→    }
   323→    
   324→    if (request.maxSurface) {
   325→      params.append("refine.surface_habitable_max", request.maxSurface.toString());
   326→    }
   327→    
   328→    params.append("rows", request.limit.toString());
   329→    params.append("start", "0");
   330→    
   331→    return params.toString();
   332→  }
   333→
   334→  /**
   335→   * Effectue une requête HTTP avec gestion des erreurs
   336→   */
   337→  private async makeRequest(endpoint: string, params?: string): Promise<DPERawResponse> {
   338→    const url = `${this.baseUrl}${endpoint}${params ? `?${params}` : ''}`;
   339→    
   340→    const headers: Record<string, string> = {
   341→      "Content-Type": "application/json",
   342→      "Accept": "application/json",
   343→    };
   344→    
   345→    if (this.apiKey) {
   346→      headers.Authorization = `Bearer ${this.apiKey}`;
   347→    }
   348→    
   349→    const controller = new AbortController();
   350→    const timeoutId = setTimeout(() => controller.abort(), this.timeout);
   351→    
   352→    try {
   353→      let response: Response;
   354→      let attempt = 0;
   355→
   356→      do {
   357→        attempt++;
   358→        // eslint-disable-next-line no-await-in-loop -- Retry logic requires sequential attempts
   359→        response = await fetch(url, {
   360→          method: "GET",
   361→          headers,
   362→          signal: controller.signal,
   363→        });
   364→
   365→        if (response.ok || attempt >= this.maxRetries) {
   366→          break;
   367→        }
   368→
   369→        // Attendre avant de réessayer (backoff exponentiel)
   370→        // eslint-disable-next-line no-await-in-loop -- Intentional delay between retry attempts
   371→        await new Promise(resolve =>
   372→          setTimeout(resolve, Math.pow(2, attempt) * 1000)
   373→        );
   374→      } while (attempt < this.maxRetries);
   375→      
   376→      if (!response.ok) {
   377→        const errorText = await response.text();
   378→        throw new Error(`HTTP ${response.status}: ${errorText}`);
   379→      }
   380→      
   381→      return await response.json();
   382→    } catch (error) {
   383→      if (error instanceof Error && error.name === "AbortError") {
   384→        throw new DPEAPIError("Timeout de la requête DPE");
   385→      }
   386→      throw error;
   387→    } finally {
   388→      clearTimeout(timeoutId);
   389→    }
   390→  }
   391→
   392→  /**
   393→   * Parse la réponse de recherche
   394→   */
   395→  private parseSearchResponse(rawResponse: DPERawResponse): DPESearchResponse {
   396→    const records = rawResponse.records ?? [];
   397→    const total = rawResponse.nhits ?? rawResponse.total_count ?? 0;
   398→
   399→    const results: DPE[] = [];
   400→
   401→    for (const record of records) {
   402→      try {
   403→        if (record.fields) {
   404→          const normalized = normalizeDPERawData({
   405→            ...record.fields,
   406→            id: record.recordid,
   407→          });
   408→          const validated = validateDPEData(normalized);
   409→          results.push(validated);
   410→        }
   411→      } catch (error) {
   412→        console.debug("Erreur de parsing d'un enregistrement DPE:", error);
   413→        // Continuer avec les autres enregistrements
   414→      }
   415→    }
   416→    
   417→    return {
   418→      results,
   419→      total,
   420→      page: 1,
   421→      pageSize: results.length,
   422→    };
   423→  }
   424→
   425→  /**
   426→   * Parse une réponse unique
   427→   */
   428→  private parseSingleResponse(record: { fields?: Record<string, unknown> } | Record<string, unknown>): DPE {
   429→    try {
   430→      const normalized = normalizeDPERawData((record as { fields?: Record<string, unknown> }).fields ?? record);
   431→      return validateDPEData(normalized);
   432→    } catch (error) {
   433→      throw new DPEAPIError(
   434→        `Erreur de validation des données DPE: ${error instanceof Error ? error.message : 'Erreur inconnue'}`
   435→      );
   436→    }
   437→  }
   438→
   439→  /**
   440→   * Gère le rate limiting
   441→   */
   442→  private async enforceRateLimit(): Promise<void> {
   443→    const now = Date.now();
   444→    const timeSinceLastRequest = now - this.lastRequestTime;
   445→    
   446→    if (timeSinceLastRequest < this.rateLimitDelay) {
   447→      await new Promise(resolve => 
   448→        setTimeout(resolve, this.rateLimitDelay - timeSinceLastRequest)
   449→      );
   450→    }
   451→
   452→    this.lastRequestTime = Date.now();
   453→  }
   454→}

