    29→/**
    30→ * Service principal DPE - Analyse de performance énergétique
    31→ * Fournit des analyses complètes pour les biens immobiliers
    32→ */
    33→export class DPEService {
    34→  private readonly client: DPEClient;
    35→  private readonly useMockData: boolean;
    36→  private readonly cacheResults: boolean;
