   341→  private async analyzeDPE(dpe: DPE): Promise<DPEAnalysis> {
   342→    try {
   343→      // Calculer les coûts énergétiques
   344→      const energyCost = calculateEnergyCost(
   345→        dpe.energyConsumption.value,
   346→        dpe.mainEnergyType as "electricity" | "gas" | "fuel_oil" | "wood" | "network" | "other",
   347→        dpe.surface
   348→      );
   349→      
   350→      // Évaluer les risques et recommandations
   351→      const rentalRisk = assessRentalRestrictionRisk(
   352→        dpe.energyConsumption.class,
   353→        dpe.gesEmission.class
   354→      );
   355→      
   356→      const recommendations = generateRenovationRecommendations(dpe);
   357→      const renovationCost = estimateRenovationCost(recommendations);
   358→      
   359→      // Calculer les scores
   360→      const performanceScore = calculatePerformanceScore(dpe);
   361→      const efficiencyRating = assessEnergyEfficiencyRating(performanceScore);
   362→      const environmentalRating = assessEnvironmentalImpactRating(dpe.gesEmission.class);
   363→      
   364→      // Déterminer la priorité de rénovation
   365→      const renovationPriority = this.calculateRenovationPriority(
   366→        rentalRisk,
   367→        performanceScore
   368→      );
   369→      
   370→      return {
   371→        dpe,
   372→        analysisDate: new Date().toISOString(),
   373→        confidenceLevel: dpe.dataSource === "mock" ? "medium" : "high",
   374→        
   375→        // Coûts
   376→        estimatedAnnualCost: energyCost.annualAmount,
   377→        estimatedMonthlyCost: energyCost.monthlyAmount,
   378→        costComparisonToAverage: this.calculateCostComparison(dpe.energyConsumption.class),
   379→        
   380→        // Conformité réglementaire
   381→        rentalRestrictionRisk: rentalRisk,
   382→        renovationRequired: rentalRisk === "high" || rentalRisk === "critical",
   383→        renovationPriority,
   384→        estimatedRenovationCost: renovationCost,
   385→        
   386→        // Performance
   387→        performanceScore,
   388→        energyEfficiencyRating: efficiencyRating,
   389→        environmentalImpactRating: environmentalRating,
   390→        
   391→        // Recommandations
   392→        recommendations,
   393→        
   394→        // Données sources
   395→        dataSource: dpe.dataSource,
   396→      };
   397→    } catch (error) {
