   114→
   115→  private async executeRequest(
   116→    criteria: DVFSearchCriteria,
   117→    attempt = 1,
   118→  ): Promise<DVFProperty[]> {
   119→    const controller = new AbortController();
   120→    const timeoutId = setTimeout(() => controller.abort(), this.timeout);
   121→
   122→    try {
   123→      // Construction de l'URL avec les paramètres de recherche géographique
   124→      const url = this.buildSearchUrl(criteria);
   125→
   126→      logger.debug(
   127→        `🔍 [DVF] Requête API (tentative ${attempt}/${this.maxRetries}):`,
   128→        url,
   129→      );
   130→
   131→      const response = await fetch(url, {
   132→        method: "GET",
   133→        headers: {
   134→          Accept: "application/json",
   135→          "User-Agent": "ChooseWisely/1.0 (contact@choosewisely.fr)",
   136→        },
   137→        signal: controller.signal,
   138→      });
   139→
   140→      clearTimeout(timeoutId);
   141→
   142→      if (!response.ok) {
   143→        if (response.status === 404) {
   144→          throw new DVFDataNotFoundError();
   145→        }
   146→
   147→        const errorText = await response.text().catch(() => "Erreur inconnue");
   148→        throw new DVFAPIError(
   149→          `Erreur API DVF: ${response.status} - ${errorText}`,
   150→          response.status,
   151→        );
   152→      }
   153→
   154→      const data = await response.json();
   155→
   156→      return this.transformApiResponse(data);
   157→    } catch (error) {
   158→      clearTimeout(timeoutId);
   159→
   160→      if (
   161→        error instanceof DVFAPIError ||
   162→        error instanceof DVFDataNotFoundError
   163→      ) {
   164→        throw error;
   165→      }
   166→
   167→      // Retry logic
   168→      if (attempt < this.maxRetries) {
   169→        const delay = Math.min(1000 * Math.pow(2, attempt - 1), 5000);
   170→        logger.debug(`⏳ [DVF] Retry dans ${delay}ms`);
   171→
   172→        await new Promise((resolve) => setTimeout(resolve, delay));
   173→        return this.executeRequest(criteria, attempt + 1);
   174→      }
   175→
   176→      if (error instanceof Error && error.name === "AbortError") {
   177→        throw new DVFAPIError("Timeout lors de la requête DVF", 408);
   178→      }
   179→
   180→      throw new DVFAPIError(
   181→        "Erreur réseau lors de l'accès aux données DVF",
   182→        500,
   183→      );
   184→    }
   185→  }
